#include <bits/stdc++.h>
using namespace std;
#define int long long

int func(int m,int a,int n,vector<int>& pref){
    int i = 2*m - 3*a;
    int p1 = 2 * pref[a];
    int p2 = pref[i];
    int p3 = 3*pref[3*n - m];
    return p1 + p2 + p3;
}
void solve() {
    int n;
    cin>>n;
    int sz = 3*n;
    vector<int> a(sz);
    for(int i = 0;i < sz;i++){
        cin>>a[i];
    }
    
    sort(a.rbegin(),a.rend());
    vector<int> pref(sz + 1,0);
    for(int i = 0;i < sz; i++){
        pref[i + 1] = pref[i] + a[i];
    }
    
    int ans = 0;
    for(int i = 0;i <= 2*n;i++){
        int l =0;
        if(i - n > 0){
            l = i - n;
            
        }
        int r = i / 2;
        while(r - l > 2){
            int m1 = l + ( r - l) /3;
            int m2 = r - (r - l)/3;
            int v1 = func(i,m1,n,pref);
            int v2 = func(i,m2,n,pref);
            
            if(v1 < v2){
                l = m1;
            }
            else{
                r = m2;
            }
        }
        
        for(int j = l;j <= r; j++){
            int curr = func(i,j,n,pref);
            if(curr > ans){
                ans = curr;
            }
        }
    }
    cout<<ans<<endl;
}

int32_t main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--) {
	    solve();
	}
}
